/**
 * @maios/domain — entities, value objects, policies, and canonical events.
 * Global conventions (plan §4.1): UUID primary keys generated by MAIOS, tenant_id on
 * every tenant-owned row, timestamptz UTC with occurred_at vs recorded_at, E.164 phone
 * normalization with raw preserved, integer minor units for money, soft deletion via
 * archived_at, optimistic concurrency via row_version.
 */
export * from './events.js';

/** Money is stored as integer minor units plus ISO currency code — never floating point. */
export interface Money {
  amountMinor: number;
  currency: string;
}

/** Contact channels preserve display value alongside the normalized comparison value. */
export interface NormalizedChannel {
  channelType: 'email' | 'phone' | 'linkedin' | 'other';
  normalizedValue: string;
  displayValue: string;
}
